<?php
require_once __DIR__ . '/config_medical.php';medical_require_permission('manage');if($_SERVER['REQUEST_METHOD']!=='POST'||!medical_verify_csrf(isset($_POST['csrf_token'])?$_POST['csrf_token']:'')){http_response_code(400);die('Bad Request');}$action=isset($_POST['action'])?$_POST['action']:'';
if($action==='equipment_add'){$asset=trim($_POST['asset_code']);$name=trim($_POST['equipment_name']);$category=trim($_POST['category']);$brand=trim($_POST['brand']);$model=trim($_POST['model']);$serial=trim($_POST['serial_no']);$dept=trim($_POST['department']);$location=trim($_POST['location']);if($name===''){medical_flash('error','กรุณาระบุชื่อเครื่องมือ');header('Location:resources.php');exit;}$display=($asset!==''?$asset.' · ':'').$name;$stmt=$conn->prepare("INSERT INTO medical_equipment(asset_code,display_name,equipment_name,category,brand,model,serial_no,department,location,status) VALUES(?,?,?,?,?,?,?,?,?,'active')");$stmt->bind_param('sssssssss',$asset,$display,$name,$category,$brand,$model,$serial,$dept,$location);$ok=$stmt->execute();$err=$stmt->error;$stmt->close();medical_flash($ok?'success':'error',$ok?'เพิ่มเครื่องมือเรียบร้อย':'เพิ่มไม่สำเร็จ: '.$err);}
elseif($action==='technician_add'){$name=trim($_POST['fullname']);$sp=trim($_POST['specialty']);$phone=trim($_POST['phone']);$email=trim($_POST['email']);if($name===''){medical_flash('error','กรุณาระบุชื่อ');header('Location:resources.php');exit;}$stmt=$conn->prepare("INSERT INTO medical_technicians(fullname,specialty,phone,email,status) VALUES(?,?,?,?,'active')");$stmt->bind_param('ssss',$name,$sp,$phone,$email);$ok=$stmt->execute();$err=$stmt->error;$stmt->close();medical_flash($ok?'success':'error',$ok?'เพิ่มรายชื่อเรียบร้อย':'เพิ่มไม่สำเร็จ: '.$err);}
elseif(in_array($action,array('equipment_toggle','technician_toggle'),true)){$id=(int)$_POST['id'];$table=$action==='equipment_toggle'?'medical_equipment':'medical_technicians';$stmt=$conn->prepare("UPDATE `$table` SET status=IF(status='active','inactive','active') WHERE id=?");$stmt->bind_param('i',$id);$stmt->execute();$stmt->close();medical_flash('success','เปลี่ยนสถานะเรียบร้อย');}
elseif(in_array($action,array('equipment_delete','technician_delete'),true)){if(!medical_is_admin()){http_response_code(403);die('Admin only');}$id=(int)$_POST['id'];$table=$action==='equipment_delete'?'medical_equipment':'medical_technicians';$stmt=$conn->prepare("DELETE FROM `$table` WHERE id=?");$stmt->bind_param('i',$id);$ok=$stmt->execute();$err=$stmt->error;$stmt->close();medical_flash($ok?'success':'error',$ok?'ลบข้อมูลเรียบร้อย':'ไม่สามารถลบได้ อาจมีรายการงานอ้างอิง: '.$err);}
header('Location:resources.php');exit;
